(()=>{'use strict';const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const project=([x,y])=>[(x+74.27)*1500,(40.93-y)*1980];
for(const f of window.BOROUGHS.features){const p=document.createElementNS(NS,'path');p.setAttribute('d',f.geometry.coordinates.map(poly=>poly.map(r=>r.map((xy,i)=>(i?'L':'M')+project(xy).map(n=>n.toFixed(2)).join(',')).join('')+'Z').join('')).join(''));p.setAttribute('fill-rule','evenodd');$('land').append(p);}
const geo=new Map(window.OFFICE_GEO.filter(g=>g.accepted).map(g=>[g.id,g]));const all=window.SCHEDULE_DATA.records.filter(r=>r.channel==='in_person'&&r.status!=='closed');const mapped=all.filter(r=>geo.has(r.id));let current=[],groups=[],selected=null,timer=null,box=[0,0,850,780];
const state=window.MapHours.state;
const services=[...new Set(mapped.map(r=>r.service))].sort();$('service').innerHTML+='<option disabled>────────</option>'+services.map(s=>`<option>${esc(s)}</option>`).join('');
function rebuild(){current=mapped.filter(r=>$('service').value==='all'||r.service===$('service').value);const by=new Map();for(const r of current){const g=geo.get(r.id),key=g.coordinates.join(',');if(!by.has(key))by.set(key,{coordinates:g.coordinates,records:[]});by.get(key).records.push(r);}groups=[...by.values()];$('dots').replaceChildren();groups.forEach((g,i)=>{const c=document.createElementNS(NS,'circle');const [x,y]=project(g.coordinates);c.setAttribute('cx',x);c.setAttribute('cy',y);c.setAttribute('r',5);c.setAttribute('tabindex','0');c.setAttribute('role','button');c.onclick=()=>show(i);c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show(i);}};g.dot=c;$('dots').append(c);});selected=null;$('detail').hidden=true;render();}
function render(){const d=+$('day').value,t=+$('time').value;let open=0,known=0,unknown=0;for(const r of current){const s=state(r,d,t);if(s==='unknown')unknown++;else{known++;if(s==='on')open++;}}$('openCount').textContent=open;$('totalCount').textContent=known;$('unknown').textContent=`${unknown} hours unknown · mapped inventory`;
for(const g of groups){const ss=g.records.map(r=>state(r,d,t));const st=ss.includes('on')?'on':ss.includes('unknown')?'unknown':'off';g.dot.setAttribute('class','map-dot '+st);g.dot.setAttribute('aria-label',`${g.records[0].address}: ${ss.filter(s=>s==='on').length} of ${g.records.length} services open; press for details`);}
const h=Math.floor(t/60),m=t%60;$('clock').textContent=`${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`;$('time').setAttribute('aria-valuetext',$('clock').textContent);$('sun').textContent=h>=6&&h<18?'☀':'☾';$('workBand').hidden=d>4;const light=h>=7&&h<18;document.documentElement.style.setProperty('--land',light?'#355761':'#203e4c');document.querySelectorAll('[data-time]').forEach(b=>b.classList.toggle('active',+b.dataset.time===t&&+b.dataset.day===d));if(selected!==null)details();}
function show(i){stop();selected=i;$('detail').hidden=false;details();$('closeDetail').focus();}
function details(){const g=groups[selected],d=+$('day').value,t=+$('time').value;$('detailBody').innerHTML=`<h2>${esc(g.records[0].address)}</h2>${g.records.map(r=>{const s=state(r,d,t);return `<article><h3>${esc(r.service)}</h3><p>${esc(r.name)}</p><p class="status ${s==='off'?'off':''}">${s==='on'?'Within regular hours':s==='unknown'?'Hours unverified':'Outside regular hours'}</p><p>${esc(r.hoursText)}</p>${r.exceptionsText?'<p>'+esc(r.exceptionsText)+'</p>':''}<details><summary>Can I skip the trip?</summary><p>${esc(r.remoteAlternative||'No remote alternative verified in this record.')}</p><p>${esc(r.appointment||'')}</p></details><p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Official source ↗</a></p></article>`;}).join('')}`;}
function stop(){clearInterval(timer);timer=null;$('play').textContent='▶';$('play').setAttribute('aria-label','Play the day');}
$('play').onclick=()=>{if(timer){stop();return;}$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause the day');timer=setInterval(()=>{const n=+$('time').value+15;if(n>1435){$('time').value=1435;stop();}else $('time').value=n;render();},150);};
$('time').oninput=()=>{stop();render();};$('day').onchange=()=>{stop();render();};$('service').onchange=()=>{stop();rebuild();};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{stop();$('time').value=b.dataset.time;$('day').value=b.dataset.day;render();});$('closeDetail').onclick=()=>{$('detail').hidden=true;if(selected!==null)groups[selected].dot.focus();selected=null;};
const about=()=>{stop();$('method').showModal();};$('about').onclick=about;$('coverage').onclick=about;$('closeMethod').onclick=()=>$('method').close();$('coverageText').textContent=`Snapshot: ${window.SCHEDULE_DATA.checkedDate}. ${mapped.length} mapped active in-person service records; ${all.length-mapped.length} active in-person records could not be mapped. Borough geometry: NYC Department of City Planning, NYC Open Data dataset gthc-hcne. Sources are linked from each office.`;
function view(){$('map').setAttribute('viewBox',box.join(' '));}function zoom(k){const w=box[2]*k,h=box[3]*k;if(w<180||w>1700)return;box=[box[0]+(box[2]-w)/2,box[1]+(box[3]-h)/2,w,h];view();}$('zoomIn').onclick=()=>zoom(.75);$('zoomOut').onclick=()=>zoom(1.333);$('resetMap').onclick=()=>{box=[0,0,850,780];view();};let drag=null;$('map').onpointerdown=e=>{if(e.target.closest('.map-dot'))return;drag={x:e.clientX,y:e.clientY,b:[...box]};$('map').setPointerCapture(e.pointerId);};$('map').onpointermove=e=>{if(!drag)return;const rect=$('map').getBoundingClientRect(),scale=Math.max(box[2]/rect.width,box[3]/rect.height);box=[drag.b[0]-(e.clientX-drag.x)*scale,drag.b[1]-(e.clientY-drag.y)*scale,box[2],box[3]];view();};$('map').onpointerup=()=>drag=null;$('map').onpointercancel=()=>drag=null;document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});view();rebuild();})();
